{
  "summary": [
    {
      "text": "Рассматривается задача о притоке к галерее с постоянным дебитом в полубесконечном пласте.",
      "claims": [
        "c1"
      ]
    },
    {
      "text": "Математически это интегрирование уравнения фильтрации с новыми начальными и граничными условиями.",
      "claims": [
        "c2",
        "c3"
      ]
    }
  ],
  "how_it_works": [
    {
      "text": "В полубесконечном пласте в момент t=0 пущена в эксплуатацию галерея.",
      "claims": [
        "c1"
      ]
    },
    {
      "text": "На галерее поддерживается постоянный объемный дебит Q.",
      "claims": [
        "c1"
      ]
    },
    {
      "text": "Требуется найти давление в любой точке пласта в любой момент времени.",
      "claims": [
        "c1"
      ]
    },
    {
      "text": "Задача сводится к интегрированию уравнения (23.22).",
      "claims": [
        "c2"
      ]
    },
    {
      "text": "Используются иные начальные и граничные условия, чем в случае с постоянным давлением.",
      "claims": [
        "c2",
        "c3"
      ]
    },
    {
      "text": "Первое условие: при t=0 давление p(x,t) равно контурному давлению pк.",
      "claims": [
        "c3",
        "c4"
      ]
    },
    {
      "text": "Это означает, что до пуска галереи давление во всех точках пласта постоянно и равно контурному.",
      "claims": [
        "c4"
      ]
    },
    {
      "text": "Второе условие: при x=0 и t>0 скорость фильтрации w(x,t) постоянна.",
      "claims": [
        "c3",

        "c5"
      ]
    },
    {
      "text": "Скорость фильтрации w связана с градиентом давления через коэффициент проницаемости k и вязкость μ.",
      "claims": [
        "c3"
      ]
    },
    {
      "text": "Постоянство дебита на галерее задается вторым условием.",
      "claims": [
        "c5"
      ]
    },
    {
      "text": "Третье условие: при t>0 и x стремящемся к бесконечности давление p(x,t) равно pк.",
      "claims": [
        "c3",
        "c6"
      ]
    },
    {
      "text": "Из третьего условия следует, что граница возмущенной зоны перемещается к бесконечности с ростом времени.",
      "claims": [
        "c6"
      ]
    }
  ],
  "steps": [
    {
      "text": "Определяется область: полубесконечный пласт.",
      "claims": [
        "c1"
      ]
    },
    {
      "text": "В момент t=0 галерея пущена в эксплуатацию.",
      "claims": [
        "c1"
      ]
    },
    {
      "text": "Устанавливается режим работы: постоянный объемный дебит Q на галерее.",
      "claims": [
        "c1"
      ]
    },
    {
      "text": "Формулируется математическая задача: интегрирование уравнения (23.22).",
      "claims": [
        "c2"
      ]
    },
    {
      "text": "Задаются начальные условия: p(x,0) = pк.",
      "claims": [
        "c3",
        "c4"
      ]
    },
    {
      "text": "Задаются граничные условия на галерее (x=0): постоянный дебит (постоянная скорость фильтрации).",
      "claims": [
        "c3",
        "c5"
      ]
    },
    {
      "text": "Задаются граничные условия на границе пласта (x→∞): давление равно контурному.",
      "claims": [
        "c3",
        "c6"
      ]
    }
  ],
